CREATE TABLE IF NOT EXISTS `docs` (`id` TEXT NOT NULL, `title` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, `pageCount` INTEGER NOT NULL, `sizeBytes` INTEGER NOT NULL, `folder` TEXT, `tags` TEXT NOT NULL, `ocrText` TEXT NOT NULL, `locked` INTEGER NOT NULL, `deleted` INTEGER NOT NULL, `coverPath` TEXT NOT NULL DEFAULT '', `ocrCorrection` TEXT NOT NULL DEFAULT '', `ocrLegacyText` TEXT NOT NULL DEFAULT '', `favorite` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_docs_updatedAt` ON `docs` (`updatedAt`);
CREATE TABLE IF NOT EXISTS `pages` (`id` TEXT NOT NULL, `docId` TEXT NOT NULL, `pageIndex` INTEGER NOT NULL, `filePath` TEXT NOT NULL, `width` INTEGER NOT NULL, `height` INTEGER NOT NULL, `sourcePath` TEXT NOT NULL DEFAULT '', `quarterTurns` INTEGER NOT NULL DEFAULT 0, `cropPoints` TEXT NOT NULL DEFAULT '', `filter` TEXT NOT NULL DEFAULT 'AUTO', `brightness` REAL NOT NULL DEFAULT 0, `contrast` REAL NOT NULL DEFAULT 1, `deleted` INTEGER NOT NULL DEFAULT 0, `updatedAt` INTEGER NOT NULL DEFAULT 0, `ocrText` TEXT NOT NULL DEFAULT '', `ocrMode` TEXT NOT NULL DEFAULT '', `ocrUpdatedAt` INTEGER NOT NULL DEFAULT 0, `fineRotation` REAL NOT NULL DEFAULT 0, `ocrLayout` TEXT NOT NULL DEFAULT '', `cropRatio` REAL NOT NULL DEFAULT 0, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_pages_docId` ON `pages` (`docId`);
